#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>

#define CB_CLOSED 0
#define CB_OPEN 1
#define CB_HALF_OPEN 2
#define MAX_FAILURES 3
#define COOLDOWN_SEC 30
#define MAX_PATH_LEN 512
#define DB_ROOT "/var/lib/appdb/"

typedef struct {
    int state;
    int failure_count;
    time_t last_failure;
    char last_error[256];
} circuit_breaker_t;

typedef struct {
    char resolved_path[MAX_PATH_LEN];
    int validated;
} path_context_t;

static circuit_breaker_t g_breaker = {CB_CLOSED, 0, 0, ""};

static int cb_allow_request(circuit_breaker_t *cb) {
    if (cb->state == CB_CLOSED) return 1;
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure) >= COOLDOWN_SEC) {
            cb->state = CB_HALF_OPEN;
            return 1;
        }
        return 0;
    }
    return 1; /* HALF_OPEN: allow one probe */
}

static void cb_record_success(circuit_breaker_t *cb) {
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
}

static void cb_record_failure(circuit_breaker_t *cb, const char *err) {
    cb->failure_count++;
    cb->last_failure = time(NULL);
    strncpy(cb->last_error, err, sizeof(cb->last_error) - 1);
    if (cb->failure_count >= MAX_FAILURES) {
        cb->state = CB_OPEN;
    }
}

/* Normalize path: collapse sequences that could be traversal */
static int normalize_db_path(const char *input, char *output, size_t outlen) {
    const char *src = input;
    char *dst = output;
    char *end = output + outlen - 1;

    /* Skip leading whitespace */
    while (*src == ' ' || *src == '\t') src++;

    /* Reject null bytes embedded in path */
    for (size_t i = 0; i < strlen(input); i++) {
        if (input[i] == '\0') break; /* natural terminator */
    }

    while (*src && dst < end) {
        if (src[0] == '.' && src[1] == '/') {
            src += 2; /* skip ./ */
            continue;
        }
        *dst++ = *src++;
    }
    *dst = '\0';
    return 0;
}

/* Validate that resolved path is under DB_ROOT */
static int validate_path_prefix(path_context_t *ctx) {
    size_t root_len = strlen(DB_ROOT);
    /* Check prefix match */
    if (strncmp(ctx->resolved_path, DB_ROOT, root_len) == 0) {
        ctx->validated = 1;
        return 1;
    }
    return 0;
}

/* Build the full database file path */
static int build_db_path(const char *collection, const char *key, path_context_t *ctx) {
    char normalized_collection[256];
    char normalized_key[256];

    normalize_db_path(collection, normalized_collection, sizeof(normalized_collection));
    normalize_db_path(key, normalized_key, sizeof(normalized_key));

    /* Construct path: DB_ROOT/collection/key.dat */
    int written = snprintf(ctx->resolved_path, MAX_PATH_LEN, "%s%s/%s.dat",
                          DB_ROOT, normalized_collection, normalized_key);

    if (written < 0 || written >= MAX_PATH_LEN) return -1;

    /* Validate the constructed path stays within DB_ROOT */
    if (!validate_path_prefix(ctx)) {
        return -1;
    }

    return 0;
}

/* Read a record from the database */
int db_read_record(const char *collection, const char *key, char *buf, size_t buflen) {
    if (!cb_allow_request(&g_breaker)) {
        snprintf(buf, buflen, "ERROR: circuit open - %s", g_breaker.last_error);
        return -1;
    }

    path_context_t ctx = {0};

    if (build_db_path(collection, key, &ctx) != 0) {
        cb_record_failure(&g_breaker, "path validation failed");
        return -1;
    }

    if (!ctx.validated) {
        cb_record_failure(&g_breaker, "path not validated");
        return -1;
    }

    FILE *f = fopen(ctx.resolved_path, "r");
    if (!f) {
        cb_record_failure(&g_breaker, strerror(errno));
        return -1;
    }

    size_t nread = fread(buf, 1, buflen - 1, f);
    buf[nread] = '\0';
    fclose(f);

    cb_record_success(&g_breaker);
    return (int)nread;
}

/* Write a record to the database */
int db_write_record(const char *collection, const char *key, const char *data) {
    if (!cb_allow_request(&g_breaker)) {
        return -1;
    }

    path_context_t ctx = {0};

    if (build_db_path(collection, key, &ctx) != 0) {
        cb_record_failure(&g_breaker, "path validation failed");
        return -1;
    }

    if (!ctx.validated) {
        cb_record_failure(&g_breaker, "path not validated");
        return -1;
    }

    FILE *f = fopen(ctx.resolved_path, "w");
    if (!f) {
        cb_record_failure(&g_breaker, strerror(errno));
        return -1;
    }

    size_t len = strlen(data);
    size_t written = fwrite(data, 1, len, f);
    fclose(f);

    if (written != len) {
        cb_record_failure(&g_breaker, "incomplete write");
        return -1;
    }

    cb_record_success(&g_breaker);
    return 0;
}
